/* Generated by tools/ps2_tile_budget.py — RAM working set for the
 * PS2 desktop.  Game payloads (PAK, ROMs) stay on the disc.
 *
 * Boot set is Quake at 80% of 800x600, centered, with a command-line
 * terminal under it (slight margin).  Other apps open from the terminal
 * or the global menu.
 */
#ifndef BTRON_PS2_TILE_H
#define BTRON_PS2_TILE_H

#define PS2_BUDGET_HEAP_KB        6400
#define PS2_BUDGET_GTERM_HIST     512
#define PS2_BUDGET_TEDITOR_ROWS   200
#define PS2_BUDGET_TEDITOR_COLS   128
#define PS2_TILE_SCREEN_W         800
#define PS2_TILE_SCREEN_H         600
#define PS2_TILE_PANEL            28
#define PS2_TILE_CASCADE          0
#define PS2_TILE_TAB_STEP         0
#define PS2_TILE_N                2
#define PS2_TILE_LIVE_MS          16
#define PS2_TILE_REST_MS          100
#define PS2_TILE_GL_PER_PASS      1
#define PS2_TILE_UI_PACE_US       1000
#define PS2_TILE_SKIP_WAVE        1
#define PS2_TILE_QUAKE_ALONE_FPS  54
#define PS2_TILE_FPS_EACH         54

enum {
    PS2_TILE_QUAKE = 0,
    PS2_TILE_TERM = 1
};

typedef struct { int x, y, w, h; } ps2_tile_rect_t;

static inline const ps2_tile_rect_t *ps2_tile_rect(int id)
{
    static const ps2_tile_rect_t r[PS2_TILE_N] = {
        { 80, 28, 640, 480 }, /* quake */
        { 80, 516, 640, 76 }, /* term */
    };
    if (id < 0 || id >= PS2_TILE_N) return 0;
    return &r[id];
}

int ps2_tile_open_standard(void);

#endif /* BTRON_PS2_TILE_H */
